use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so the node asks for the names it knows, in order.
const KEYS: [&str; 5] = ["urls", "subscriptions", "feeds", "list", "all"];

/// Collect every JSON string literal in `s`, with escapes decoded.
fn json_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        loop {
            match chars.next() {
                None => return out,
                Some('"') => break,
                Some('\\') => match chars.next() {
                    None => return out,
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') => cur.push('\u{8}'),
                    Some('f') => cur.push('\u{c}'),
                    Some('u') => {
                        let mut v: u32 = 0;
                        for _ in 0..4 {
                            if let Some(h) = chars.next().and_then(|h| h.to_digit(16)) {
                                v = v * 16 + h;
                            }
                        }
                        if let Some(ch) = char::from_u32(v) {
                            cur.push(ch);
                        }
                    }
                    Some(o) => cur.push(o),
                },
                Some(o) => cur.push(o),
            }
        }
        out.push(cur);
    }
    out
}

/// Parse a stored value into URLs. Accepts a JSON document (an array of
/// strings, or an object holding one) or plain text with one URL per line or
/// whitespace-separated, with `#` comment lines ignored.
fn parse_urls(raw: &str) -> Vec<String> {
    let text = raw.trim();
    let mut out: Vec<String> = Vec::new();
    if text.starts_with('[') || text.starts_with('{') || text.starts_with('"') {
        for s in json_strings(text) {
            let s = s.trim();
            if s.contains("://") {
                out.push(s.to_string());
            }
        }
    } else {
        for line in text.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            for tok in line.split_whitespace() {
                let tok = tok.trim_matches(|c| c == ',' || c == ';');
                if !tok.is_empty() {
                    out.push(tok.to_string());
                }
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS.iter() {
            if let Some(value) = state_read::get(key) {
                for u in parse_urls(&value) {
                    if !urls.contains(&u) {
                        urls.push(u);
                    }
                }
                if !urls.is_empty() {
                    break;
                }
            }
        }
        if urls.is_empty() {
            // The contract requires a non-empty list; with nothing in the
            // store there is no honest output, so fail rather than invent one.
            panic!("no subscriptions found in state store");
        }
        SubscriptionList { urls }
    }
}

export!(Node);
